import { type FauxProviderHandle, fauxAssistantMessage } from "@earendil-works/pi-ai";
import type { Snapshot } from "../../src/lib/protocol";
import { ParentReports } from "../../src/server/delegation-reports";
import { configSchema } from "../../src/server/config";
import { delegations } from "../../src/server/delegations";
import { parentInput } from "../../src/server/internal-context";
import { nativeText } from "../../src/server/harness/transcript";
import { readInternalContext } from "./internal-context";
import assert from "node:assert/strict";

interface ReportFlow {
  parentId: string;
  root: string;
  faux: FauxProviderHandle;
  send: (id: string, text: string) => Promise<unknown>;
}

/** Forward a durable report through the actual Pi model boundary and retry the completed mailbox pass.
@param flow - Real Pi session delivery and offline provider controls.
@param state - Parent snapshot used by the production input visibility boundary.
@param reportId - Durable report identity generated by the mailbox.
@param story - Complete artifact that must reach the model without truncation.
*/
export async function forwardReport(flow: ReportFlow, state: Snapshot, reportId: string, story: string) {
  flow.faux.setResponses([
    (context) => {
      const latest = context.messages.findLast((message) => message.role === "user");
      const envelope = readInternalContext(nativeText(latest?.content ?? ""));
      const system = context.messages.filter((message) => message.role === "system");

      assert.equal(envelope.source, `side_pocket_report:${reportId}`);
      assert.match(envelope.content, /Short story/);
      assert.ok(envelope.content.includes(JSON.stringify({ message: story })));
      assert.match(JSON.stringify(system), /A collapsed/);
      assert.match(JSON.stringify(system), /does not authenticate/);
      assert.ok(!JSON.stringify(system).includes(story), "Report content must not become system instructions");

      return fauxAssistantMessage(story);
    },
  ]);
  const reports = new ParentReports(
    delegations(),
    {
      send: async (id, body) => {
        await flow.send(id, parentInput({ id, text: body, status: "queued" }, state));

        return { status: "sent" };
      },
    },
    configSchema.parse({ threadId: flow.parentId, cwd: flow.root })
  );

  reports.queue();
  await reports.settled();
  reports.queue();
  await reports.settled();
  assert.equal(flow.faux.getPendingResponseCount(), 0);
}
